const std = @import("std");
const enr = @import("enr.zig");

pub fn parse(allocator: std.mem.Allocator, strings: []const []const u8) ![]enr.Record {
    var enrs = try allocator.alloc(enr.Record, strings.len);
    for (strings, 0..) |str, index| {
        enrs[index] = try enr.decodeText(str);
    }
    return enrs;
}

